var t=`0681-to`;var n=`world-0681`;var s=`ML`;var r=`western-africa`;var o=8;var a=42;var l={en:`Tô`,ua:`То`};var g={en:`Tô is a Mali classic prepared with millet flour, plain yogurt. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`То, страва кухні країни Малі зі складниками: пшоняне борошно, натуральний йогурт. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`water`,1e3,`ml`],[`table-salt`,4,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 22 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 22 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:22,i:[[`millet-flour`,330,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:7,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`plain-yogurt`,210,`g`]]}];var d={slug:t,id:n,country:`ML`,region:r,servings:8,minutes:42,title:l,text:g,steps:u};export{s as country,d as default,n as id,a as minutes,r as region,o as servings,t as slug,u as steps,g as text,l as title};